// Polices Sora et Manrope (sous-ensemble latin, licence OFL) auto-hébergées : la CSP reste font-src 'self',
// aucune requête vers un tiers. Générées depuis site/fonts/*.woff2.
const SORA = "";
const MANROPE = "";

const cache = new Map();
function bytes(b64) { return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)); }

/** Réponse pour /assets/<nom>.woff2, ou null si la police n'existe pas. */
export function fontResponse(name) {
  const src = { "sora.woff2": SORA, "manrope.woff2": MANROPE }[name];
  if (!src) return null;
  if (!cache.has(name)) cache.set(name, bytes(src));
  return new Response(cache.get(name), { headers: { "content-type": "font/woff2", "cache-control": "public, max-age=31536000, immutable", "x-content-type-options": "nosniff" } });
}
